# Generated by Antigravity CLI 1.4.2 (Gemini 3.8 Flash (High))
"""
Recursively resolves, copies, and relinks non-system dynamic libraries
into a macOS application bundle's Frameworks directory.
"""

import argparse
import os
import re
import shutil
import subprocess
import sys


def get_dependencies(path):
    output = subprocess.check_output(["otool", "-L", path]).decode()
    deps = []
    # Skip first line (path itself)
    for line in output.splitlines()[1:]:
        m = re.match(r"\s+([^\s]+)", line)
        if m:
            dep = m.group(1)
            # Skip system frameworks and libraries
            if not (dep.startswith("/usr/lib/") or dep.startswith("/System/Library/")):
                deps.append(dep)
    return deps


def main():
    parser = argparse.ArgumentParser(description="Bundle and relink dynamic libraries into macOS bundle.")
    parser.add_argument("--frameworks-dir", required=True, help="Destination Frameworks directory")
    parser.add_argument("binaries", nargs="+", help="Mach-O binaries to inspect and relink")
    args = parser.parse_args()

    fw_dir = os.path.abspath(args.frameworks_dir)
    os.makedirs(fw_dir, exist_ok=True)

    binaries = [os.path.abspath(b) for b in args.binaries if os.path.exists(b)]
    if not binaries:
        print("Error: No existing binaries provided to bundle-dylibs.", file=sys.stderr)
        return 1

    copied_dylibs = {}
    queue = list(binaries)

    # Breadth-first traversal of non-system dylib dependencies
    while queue:
        curr = queue.pop(0)
        deps = get_dependencies(curr)
        for dep in deps:
            if dep.startswith("@rpath/"):
                continue

            base = os.path.basename(dep)
            dest_dylib = os.path.join(fw_dir, base)

            if base not in copied_dylibs:
                real_dep = os.path.realpath(dep)
                shutil.copy2(real_dep, dest_dylib)
                os.chmod(dest_dylib, 0o755)
                copied_dylibs[base] = dest_dylib
                queue.append(dest_dylib)

            # Relink current file to load dylib via @rpath
            subprocess.check_call(["install_name_tool", "-change", dep, f"@rpath/{base}", curr])

    # Assign @rpath IDs to bundled dylibs
    for base, dylib in copied_dylibs.items():
        subprocess.check_call(["install_name_tool", "-id", f"@rpath/{base}", dylib])

    # Add @executable_path/../Frameworks to rpath of each binary
    for b in binaries:
        load_cmds = subprocess.check_output(["otool", "-l", b]).decode()
        if "@executable_path/../Frameworks" not in load_cmds:
            subprocess.check_call(["install_name_tool", "-add_rpath", "@executable_path/../Frameworks", b])

    print(f"    Relinked {len(copied_dylibs)} dynamic libraries into {fw_dir}.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
